using System; using System.Reflection; using HarmonyLib; using VRageMath; namespace AudioFix { public class Loader : AppDomainManager { private static bool _patched = false; public override void InitializeNewDomain(AppDomainSetup info) { base.InitializeNewDomain(info); if (!_patched) { _patched = true; AppDomain.CurrentDomain.AssemblyLoad += OnAssemblyLoad; } } private static void OnAssemblyLoad(object sender, AssemblyLoadEventArgs args) { if (args.LoadedAssembly.GetName().Name == "VRage.Audio") { var harmony = new Harmony("com.community.se.audiofix"); var targetType = args.LoadedAssembly.GetType("VRage.Audio.MyXAudio2"); var targetMethod = targetType.GetMethod("Update", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, new Type[] { typeof(int), typeof(Vector3), typeof(Vector3), typeof(Vector3), typeof(Vector3) }, null); var prefix = typeof(Loader).GetMethod("UpdatePrefix", BindingFlags.Static | BindingFlags.NonPublic); harmony.Patch(targetMethod, prefix: new HarmonyMethod(prefix)); } } private static void UpdatePrefix(ref Vector3 listenerUp, ref Vector3 listenerFront) { listenerFront = -listenerFront; listenerUp = -listenerUp; } } }
